api.look('agent');
const cx=api.w/2, cy=340, k=api.seg(t,0,1.4);
const beat=1+0.06*Math.max(0,Math.sin(t*Math.PI*2.2));
api.path('M0 90 C-130 10 -120 -80 -60 -80 C-25 -80 0 -55 0 -40 C0 -55 25 -80 60 -80 C120 -80 130 10 0 90 Z',{x:cx,y:cy,s:1.7*beat,c:'accent',w:5,fill:'accent',k});
api.text('Heart',cx,cy+190,{size:36,align:'center',k:api.seg(t,1,2)});
api.say('The heart is a pump',0.3,3.2);

api.look('agent');
const cx=api.w/2, cy=340;
api.path('M0 90 C-130 10 -120 -80 -60 -80 C-25 -80 0 -55 0 -40 C0 -55 25 -80 60 -80 C120 -80 130 10 0 90 Z',{x:cx,y:cy,s:1.7,c:'accent',w:5,fill:'accent',a:0.25});
api.line(cx,cy-70,cx,cy+120,{w:4,k:api.seg(t,0,1)});
api.line(cx-190,cy+10,cx+190,cy+10,{w:4,k:api.seg(t,0.4,1.4)});
api.callout('Right atrium',cx-80,cy-50,90,cy-150,{k:api.seg(t,1.5,2.5),c:'a2'});
api.callout('Left atrium',cx+80,cy-50,300,cy-150,{k:api.seg(t,2.5,3.5),c:'accent'});
api.callout('Right ventricle',cx-80,cy+70,90,cy+190,{k:api.seg(t,3.5,4.5),c:'a2'});
api.callout('Left ventricle',cx+80,cy+70,300,cy+190,{k:api.seg(t,4.5,5.5),c:'accent'});
api.say('Four chambers, two sides',0.3,5.5);

api.look('agent');
const cx=api.w/2, cy=330;
api.path('M0 90 C-130 10 -120 -80 -60 -80 C-25 -80 0 -55 0 -40 C0 -55 25 -80 60 -80 C120 -80 130 10 0 90 Z',{x:cx,y:cy,s:1.7,c:'fg',w:3,fill:'accent',a:0.2});
const L=[[cx-150,cy-230],[cx-150,cy-80],[cx-70,cy+20],[cx-50,cy+60]];
api.curve(60,cy-240,cx-120,cy-300,cx-60,cy-60,{c:'a2',w:6,k:api.seg(t,0,1.5)});
api.curve(cx+50,cy-60,cx+130,cy-300,api.w-50,cy-240,{c:'accent',w:6,k:api.seg(t,2.5,4)});
api.swarm(40,t,{mode:'flock',cx:cx-80,cy:cy-100,rx:70,ry:70,c:'a2'});
api.label('Blue: low oxygen',100,cy+200,{k:api.seg(t,0.5,1.5)});
api.label('Red: oxygen-rich',api.w-110,cy+250,{k:api.seg(t,3,4)});
api.text('Lungs',cx,cy-270,{size:30,align:'center',k:api.seg(t,1.5,2.5)});
api.text('Body',api.w-70,cy-200,{size:26,align:'center',k:api.seg(t,4,5)});
api.say('Lungs refill it, body uses it',0.3,5.8);

api.look('agent');
const cx=api.w/2, cy=340;
const ph=(t%1.6)/1.6, sq=api.seg(ph,0.1,0.35)*(1-api.seg(ph,0.5,0.8));
api.path('M0 90 C-130 10 -120 -80 -60 -80 C-25 -80 0 -55 0 -40 C0 -55 25 -80 60 -80 C120 -80 130 10 0 90 Z',{x:cx,y:cy,s:1.7*(1+0.08*sq),c:'accent',w:5,fill:'accent'});
api.swarm(60,t,{mode:'rise',cx:cx,cy:cy-120,rx:70,ry:140,c:'accent'});
api.glow(cx,cy,100+60*sq,{c:'accent'});
api.text('Squeeze',cx,cy+200,{size:34,align:'center',a:sq*0.7+0.3});
api.text('Relax',cx,cy+245,{size:34,align:'center',a:(1-sq)*0.7+0.3,c:'a2'});
api.say('Squeeze pushes, relax refills',0.3,5.8);

api.look('agent');
const cx=api.w/2, cy=300;
api.path('M0 90 C-130 10 -120 -80 -60 -80 C-25 -80 0 -55 0 -40 C0 -55 25 -80 60 -80 C120 -80 130 10 0 90 Z',{x:cx,y:cy,s:1.2*(1+0.06*Math.max(0,Math.sin(t*7.5))),c:'accent',w:4,fill:'accent'});
api.counter(72,cx,cy+190,{k:api.seg(t,0.5,2.5),suf:' bpm',size:44});
api.counter(5,cx,cy+260,{k:api.seg(t,2.5,4.5),suf:' litres a minute',size:30});
api.say('Beating all day, every day',0.3,5.8);
